use engine::game::casting::display_spell_cost;
use engine::game::combat::AttackTarget;
use engine::game::keywords::effective_keyword_instances;
use engine::game::scenario::{GameRunner, GameScenario, P0, P1};
use engine::game::scenario_db::GameScenarioDbExt;
use engine::game::zone_pipeline::{move_object_for_test, ZoneMoveRequest};
use engine::types::ability::TargetRef;
use engine::types::actions::GameAction;
use engine::types::game_state::{CastingVariant, CastingVariantChoiceOption, WaitingFor};
use engine::types::identifiers::ObjectId;
use engine::types::keywords::{FlashbackCost, Keyword, KeywordKind};
use engine::types::mana::{ManaCost, ManaCostShard, ManaRestriction, ManaType, ManaUnit};
use engine::types::phase::Phase;
use engine::types::player::PlayerId;
use engine::types::zones::Zone;

use crate::support::shared_card_db;

const PAST_IN_FLAMES: &str = "Each instant and sorcery card in your graveyard gains flashback until end of turn. The flashback cost is equal to its mana cost.\nFlashback {4}{R} (You may cast this card from your graveyard for its flashback cost. Then exile it.)";
const DESPERATE_RITUAL: &str = "Add {R}{R}{R}.\nSplice onto Arcane {1}{R} (As you cast an Arcane spell, you may reveal this card from your hand and pay its splice cost. If you do, add this card's effects to that spell.)";
const PYRETIC_RITUAL: &str = "Add {R}{R}{R}.";
const STRIKE_IT_RICH: &str = "Create a Treasure token. (It's an artifact with \"{T}, Sacrifice this token: Add one mana of any color.\")\nFlashback {2}{R} (You may cast this card from your graveyard for its flashback cost. Then exile it.)";
const BACKDRAFT_HELLKITE: &str = "Flying\nWhenever this creature attacks, each instant and sorcery card in your graveyard gains flashback until end of turn. The flashback cost is equal to its mana cost.";
const BLAZE: &str = "Blaze deals X damage to any target.";
const TORMENTING_VOICE: &str =
    "As an additional cost to cast this spell, discard a card.\nDraw two cards.";
const GRIM_CAPTAINS_LOCKER: &str = "{T}: Surveil 1. (Look at the top card of your library. You may put it into your graveyard.)\n{T}: Until end of turn, each creature card in your graveyard gains \"Escape—{3}{B}, Exile four other cards from your graveyard.\" (You may cast a card with escape from your graveyard for its escape cost.)";
const GHOST_ARK: &str = "Flying\nRepair Barge — Whenever this Vehicle becomes crewed, each artifact creature card in your graveyard gains unearth {3} until end of turn.\nCrew 2 (Tap any number of creatures you control with total power 2 or more: This Vehicle becomes an artifact creature until end of turn.)";

/// The pool's activation-only spare: it can't pay a spell, so it survives every cast below.
const SPARE_SOURCE: ObjectId = ObjectId(8_888);
const MANA_SOURCE: ObjectId = ObjectId(9_999);

fn cost(generic: u32, shards: Vec<ManaCostShard>) -> ManaCost {
    ManaCost::Cost { generic, shards }
}

/// {1}{R}, the mana cost of the rituals, Fire and Tormenting Voice.
fn one_red() -> ManaCost {
    cost(1, vec![ManaCostShard::Red])
}

/// Mana units for the color letters in `colors` (W U B R G C).
fn units(colors: &str) -> Vec<ManaUnit> {
    colors
        .chars()
        .map(|letter| {
            let color = match letter {
                'W' => ManaType::White,
                'U' => ManaType::Blue,
                'B' => ManaType::Black,
                'R' => ManaType::Red,
                'G' => ManaType::Green,
                'C' => ManaType::Colorless,
                other => panic!("no mana letter {other}"),
            };
            ManaUnit::new(color, MANA_SOURCE, false, vec![])
        })
        .collect()
}

fn spare() -> ManaUnit {
    let restriction = vec![ManaRestriction::OnlyForActivation];
    ManaUnit::new(ManaType::Red, SPARE_SOURCE, false, restriction)
}

/// P0's starting pool: `colors` and the spare.
fn pool(scenario: &mut GameScenario, colors: &str) {
    let mut pool = units(colors);
    pool.push(spare());
    scenario.with_mana_pool(P0, pool);
}

/// Fund P0's pool mid-game (the pool empties as steps end); the spare is
/// added only when the pool has none.
fn fund(runner: &mut GameRunner, colors: &str) {
    let has_spare = pool_colors(runner).contains(&(ManaType::Red, SPARE_SOURCE));
    let units = units(colors).into_iter().chain((!has_spare).then(spare));
    for unit in units {
        let _ = runner.state_mut().add_mana_to_pool(P0, unit);
    }
}

/// The pool's units as (color, source), sorted.
fn pool_colors(runner: &GameRunner) -> Vec<(ManaType, ObjectId)> {
    let mut units: Vec<_> = runner.state().players[0]
        .mana_pool
        .units()
        .map(|unit| (unit.color, unit.source_id))
        .collect();
    units.sort_by_key(|(color, source)| (format!("{color:?}"), source.0));
    units
}

/// Only the spare is left: every funded unit was spent.
fn assert_only_the_spare_is_left(runner: &GameRunner) {
    assert_eq!(
        pool_colors(runner),
        vec![(ManaType::Red, SPARE_SOURCE)],
        "everything funded was spent"
    );
}

/// Move `card` through the replacement-aware zone pipeline and check it arrived.
fn move_card(runner: &mut GameRunner, card: ObjectId, zone: Zone) {
    let needs_choice = move_object_for_test(
        runner.state_mut(),
        ZoneMoveRequest::effect(card, zone, card),
        &mut Vec::new(),
    );
    assert!(!needs_choice, "the move to {zone:?} needs no choice");
    assert_eq!(runner.state().objects[&card].zone, zone, "{card:?} moved");
}

fn assert_settled(runner: &GameRunner) {
    assert!(runner.state().stack.is_empty(), "the stack is empty");
    assert!(
        matches!(runner.state().waiting_for, WaitingFor::Priority { .. }),
        "priority returns, got {:?}",
        runner.state().waiting_for
    );
}

fn library(scenario: &mut GameScenario, player: PlayerId, count: usize) {
    for index in 0..count {
        scenario.add_card_to_library_top(player, &format!("Library {index}"));
    }
}

/// How many `CastSpell` actions the engine offers for `card`.
fn casts_offered(runner: &GameRunner, card: ObjectId) -> usize {
    legal_actions(runner.state())
        .into_iter()
        .filter(|action| matches!(action, GameAction::CastSpell { object_id, .. } if *object_id == card))
        .count()
}

fn flashbacks(runner: &GameRunner, card: ObjectId) -> Vec<Keyword> {
    effective_keyword_instances(runner.state(), card, KeywordKind::Flashback)
}

/// The flashback Past in Flames gives: its cost is the card's own mana cost.
fn granted_flashback() -> Keyword {
    Keyword::Flashback(FlashbackCost::Mana(ManaCost::SelfManaCost))
}

fn printed_flashback(generic: u32, shards: Vec<ManaCostShard>) -> Keyword {
    Keyword::Flashback(FlashbackCost::Mana(cost(generic, shards)))
}

/// The continuous effects `source` installed that are still live.
fn grants_from(runner: &GameRunner, source: ObjectId) -> usize {
    runner
        .state()
        .transient_continuous_effects
        .iter()
        .filter(|effect| effect.source_id == source)
        .count()
}

/// A clone of the board with a `CastSpell` of `card` started, so the board is unchanged.
fn probe_cast(runner: &GameRunner, card: ObjectId) -> GameRunner {
    let mut probe = GameRunner::from_state(runner.state().clone());
    let card_id = probe.state().objects[&card].card_id;
    probe
        .act(GameAction::CastSpell {
            object_id: card,
            card_id,
            targets: vec![],
            payment_mode: Default::default(),
        })
        .expect("the cast is accepted");
    probe
}

/// The options of the menu a `CastSpell` of `card` opens, or empty when the
/// cast goes on without one.
fn menu(runner: &GameRunner, card: ObjectId) -> Vec<CastingVariantChoiceOption> {
    match &probe_cast(runner, card).state().waiting_for {
        WaitingFor::CastingVariantChoice { options, .. } => options.clone(),
        _ => Vec::new(),
    }
}

/// The prompt after `CastSpell` of `card` and the choice of `player` as its one target.
fn prompt_after_target(runner: &GameRunner, card: ObjectId, player: PlayerId) -> WaitingFor {
    let mut probe = probe_cast(runner, card);
    probe
        .act(GameAction::ChooseTarget {
            target: Some(TargetRef::Player(player)),
        })
        .expect("the target is accepted");
    probe.state().waiting_for.clone()
}

struct Board {
    runner: GameRunner,
    past_in_flames: ObjectId,
    desperate_ritual: ObjectId,
    pyretic_ritual: ObjectId,
    strike_it_rich: ObjectId,
    grizzly_bears: ObjectId,
    opposing_ritual: ObjectId,
    late_ritual: ObjectId,
}

/// P0 precombat main with {3}{R} for Past in Flames. P0's graveyard holds
/// Desperate Ritual, Pyretic Ritual, Strike It Rich and Grizzly Bears; P1's
/// holds a Pyretic Ritual; P0's hand holds Past in Flames and a second Pyretic
/// Ritual (the card that reaches the graveyard after the grant).
fn board() -> Board {
    let mut scenario = GameScenario::new();
    scenario.at_phase(Phase::PreCombatMain);
    let desperate_ritual = scenario
        .add_spell_to_graveyard(P0, "Desperate Ritual", true)
        .with_subtypes(vec!["Arcane"])
        .with_mana_cost(one_red())
        .from_oracle_text(DESPERATE_RITUAL)
        .id();
    let pyretic_ritual = scenario
        .add_spell_to_graveyard(P0, "Pyretic Ritual", true)
        .with_mana_cost(one_red())
        .from_oracle_text(PYRETIC_RITUAL)
        .id();
    let strike_it_rich = scenario
        .add_spell_to_graveyard(P0, "Strike It Rich", false)
        .with_mana_cost(cost(0, vec![ManaCostShard::Red]))
        .from_oracle_text(STRIKE_IT_RICH)
        .id();
    let grizzly_bears = scenario
        .add_creature_to_graveyard(P0, "Grizzly Bears", 2, 2)
        .with_subtypes(vec!["Bear"])
        .with_mana_cost(cost(1, vec![ManaCostShard::Green]))
        .id();
    let opposing_ritual = scenario
        .add_spell_to_graveyard(P1, "Pyretic Ritual", true)
        .with_mana_cost(one_red())
        .from_oracle_text(PYRETIC_RITUAL)
        .id();
    let past_in_flames = scenario
        .add_spell_to_hand_from_oracle(P0, "Past in Flames", false, PAST_IN_FLAMES)
        .with_mana_cost(cost(3, vec![ManaCostShard::Red]))
        .id();
    let late_ritual = scenario
        .add_spell_to_hand_from_oracle(P0, "Pyretic Ritual", true, PYRETIC_RITUAL)
        .with_mana_cost(one_red())
        .id();
    library(&mut scenario, P0, 3);
    library(&mut scenario, P1, 3);
    pool(&mut scenario, "CCCR");
    Board {
        runner: scenario.build(),
        past_in_flames,
        desperate_ritual,
        pyretic_ritual,
        strike_it_rich,
        grizzly_bears,
        opposing_ritual,
        late_ritual,
    }
}

/// [`board`] with Past in Flames cast and resolved.
fn board_after_past_in_flames() -> Board {
    let mut board = board();
    board.runner.cast(board.past_in_flames).resolve();
    assert_settled(&board.runner);
    board
}

/// CR 611.2c + CR 702.34a: after Past in Flames resolves, each instant and
/// sorcery card in the caster's graveyard carries the granted flashback and is
/// offered a cast; before, the rituals had no cast at all.
#[test]
fn every_instant_and_sorcery_in_the_graveyard_gains_flashback() {
    let Board {
        mut runner,
        past_in_flames,
        desperate_ritual,
        pyretic_ritual,
        strike_it_rich,
        ..
    } = board();

    // Reach-guard: before the grant the rituals have no flashback and no cast,
    // and Strike It Rich only has its printed instance (offered, the pool pays {2}{R}).
    for ritual in [desperate_ritual, pyretic_ritual] {
        assert!(flashbacks(&runner, ritual).is_empty());
        assert_eq!(casts_offered(&runner, ritual), 0);
    }
    assert_eq!(
        flashbacks(&runner, strike_it_rich),
        vec![printed_flashback(2, vec![ManaCostShard::Red])]
    );
    assert!(casts_offered(&runner, strike_it_rich) >= 1);
    assert_eq!(grants_from(&runner, past_in_flames), 0);

    runner.cast(past_in_flames).resolve();
    assert_settled(&runner);
    fund(&mut runner, "CCR");

    for ritual in [desperate_ritual, pyretic_ritual] {
        assert_eq!(flashbacks(&runner, ritual), vec![granted_flashback()]);
        assert!(casts_offered(&runner, ritual) >= 1, "the ritual is offered");
    }
    let strike = flashbacks(&runner, strike_it_rich);
    assert_eq!(strike.len(), 2, "printed and granted: {strike:?}");
    assert!(strike.contains(&printed_flashback(2, vec![ManaCostShard::Red])));
    assert!(strike.contains(&granted_flashback()));
    assert_eq!(
        display_spell_cost(runner.state(), P0, pyretic_ritual),
        Some(one_red()),
        "the flashback cost is the card's mana cost"
    );
    assert_eq!(
        grants_from(&runner, past_in_flames),
        3,
        "one grant per instant or sorcery card"
    );
}

/// Ruling "You must still follow any timing restrictions": at the beginning of
/// combat the instant is offered and the sorcery is not, though both carry the
/// grant.
#[test]
fn the_granted_flashback_keeps_the_timing_of_the_card_type() {
    let Board {
        mut runner,
        pyretic_ritual,
        strike_it_rich,
        ..
    } = board_after_past_in_flames();
    runner.advance_to_phase(Phase::BeginCombat);
    assert_eq!(runner.state().phase, Phase::BeginCombat);
    assert_settled(&runner);
    fund(&mut runner, "CCR");

    assert!(casts_offered(&runner, pyretic_ritual) >= 1, "the instant");
    assert!(
        flashbacks(&runner, strike_it_rich).contains(&granted_flashback()),
        "reach-guard: the sorcery has the grant, only its timing refuses"
    );
    assert_eq!(casts_offered(&runner, strike_it_rich), 0, "the sorcery");
}

/// CR 702.34a: a spell cast with the granted flashback pays the card's mana
/// cost and is exiled afterward.
#[test]
fn a_granted_flashback_cast_pays_the_mana_cost_and_exiles_the_card() {
    let Board {
        mut runner,
        pyretic_ritual,
        ..
    } = board_after_past_in_flames();
    fund(&mut runner, "CR");
    assert_eq!(
        runner.state().objects[&pyretic_ritual].zone,
        Zone::Graveyard
    );

    runner.cast(pyretic_ritual).resolve();

    assert_eq!(runner.state().objects[&pyretic_ritual].zone, Zone::Exile);
    let reds = pool_colors(&runner)
        .into_iter()
        .filter(|(color, _)| *color == ManaType::Red)
        .count();
    assert_eq!(reds, 4, "the ritual's {{R}}{{R}}{{R}} and the spare");
    assert_eq!(
        pool_colors(&runner).len(),
        4,
        "the {{1}}{{R}} funded was spent"
    );
    assert_settled(&runner);
}

/// Ruling "multiple instances of flashback": Strike It Rich holds its printed
/// {2}{R} and the granted {R}. With only {R} the granted one pays; with {R}{R}{R}
/// both are offered, one option each.
#[test]
fn a_card_with_a_printed_flashback_gains_a_second_cost_option() {
    let Board {
        mut runner,
        strike_it_rich,
        ..
    } = board_after_past_in_flames();
    fund(&mut runner, "RRR");
    let options = menu(&runner, strike_it_rich);
    let costs: Vec<_> = options
        .iter()
        .map(|option| option.mana_cost.clone())
        .collect();
    assert_eq!(options.len(), 2, "{options:?}");
    assert!(costs.contains(&cost(0, vec![ManaCostShard::Red])));
    assert!(costs.contains(&cost(2, vec![ManaCostShard::Red])));

    let Board {
        mut runner,
        strike_it_rich,
        ..
    } = board_after_past_in_flames();
    fund(&mut runner, "R");
    assert!(
        menu(&runner, strike_it_rich).is_empty(),
        "one payable option"
    );
    assert!(casts_offered(&runner, strike_it_rich) >= 1);
    runner.cast(strike_it_rich).resolve();
    assert_eq!(runner.state().objects[&strike_it_rich].zone, Zone::Exile);
    assert!(runner
        .battlefield_names()
        .iter()
        .any(|name| name == "Treasure"));
    assert_only_the_spare_is_left(&runner);
}

/// CR 611.2c: a card that reaches the graveyard after Past in Flames resolved
/// does not gain the grant.
#[test]
fn a_card_put_into_the_graveyard_afterward_gains_nothing() {
    let Board {
        mut runner,
        desperate_ritual,
        late_ritual,
        ..
    } = board_after_past_in_flames();
    fund(&mut runner, "CR");
    runner.cast(late_ritual).resolve();
    assert_eq!(runner.state().objects[&late_ritual].zone, Zone::Graveyard);
    fund(&mut runner, "CR");

    assert!(flashbacks(&runner, late_ritual).is_empty());
    assert_eq!(casts_offered(&runner, late_ritual), 0);
    assert_eq!(display_spell_cost(runner.state(), P0, late_ritual), None);
    // Reach-guard: the card that was there at resolution still has it.
    assert_eq!(
        flashbacks(&runner, desperate_ritual),
        vec![granted_flashback()]
    );
    assert!(casts_offered(&runner, desperate_ritual) >= 1);
}

/// CR 400.7: a card that leaves the graveyard and comes back is a new object,
/// without the grant.
#[test]
fn a_card_that_leaves_the_graveyard_and_returns_loses_the_grant() {
    let Board {
        mut runner,
        desperate_ritual,
        pyretic_ritual,
        ..
    } = board_after_past_in_flames();
    fund(&mut runner, "CR");
    move_card(&mut runner, desperate_ritual, Zone::Hand);
    move_card(&mut runner, desperate_ritual, Zone::Graveyard);

    assert!(flashbacks(&runner, desperate_ritual).is_empty());
    assert_eq!(casts_offered(&runner, desperate_ritual), 0);
    // Reach-guard: the other card of the set still has it.
    assert_eq!(
        flashbacks(&runner, pyretic_ritual),
        vec![granted_flashback()]
    );
    assert!(casts_offered(&runner, pyretic_ritual) >= 1);
}

/// "Your graveyard" and "instant and sorcery": the opponent's card and the
/// creature card get nothing.
#[test]
fn only_the_casters_instants_and_sorceries_gain_flashback() {
    let Board {
        mut runner,
        pyretic_ritual,
        grizzly_bears,
        opposing_ritual,
        ..
    } = board_after_past_in_flames();
    fund(&mut runner, "CCR");

    assert!(flashbacks(&runner, opposing_ritual).is_empty());
    assert!(flashbacks(&runner, grizzly_bears).is_empty());
    assert_eq!(casts_offered(&runner, grizzly_bears), 0);
    assert_eq!(casts_offered(&runner, opposing_ritual), 0);
    // Reach-guard: the caster's own instant got it in the same resolution.
    assert_eq!(
        flashbacks(&runner, pyretic_ritual),
        vec![granted_flashback()]
    );
    assert!(casts_offered(&runner, pyretic_ritual) >= 1);
}

/// CR 514.2: the grant lasts until end of turn. It is still there in the end
/// step and gone with the cleanup step.
#[test]
fn the_grant_ends_at_cleanup() {
    let Board {
        mut runner,
        past_in_flames,
        pyretic_ritual,
        ..
    } = board_after_past_in_flames();
    runner.advance_to_phase(Phase::End);
    assert_eq!(runner.state().phase, Phase::End);
    assert_settled(&runner);
    fund(&mut runner, "CR");
    assert_eq!(grants_from(&runner, past_in_flames), 3);
    assert_eq!(
        flashbacks(&runner, pyretic_ritual),
        vec![granted_flashback()]
    );
    assert!(casts_offered(&runner, pyretic_ritual) >= 1, "the end step");

    runner.advance_to_phase(Phase::Upkeep);
    assert_eq!(runner.state().phase, Phase::Upkeep);
    assert!(flashbacks(&runner, pyretic_ritual).is_empty());
    assert_eq!(display_spell_cost(runner.state(), P0, pyretic_ritual), None);
    assert_eq!(grants_from(&runner, past_in_flames), 0);
}

/// CR 608.2n + CR 611.2c: the resolving spell is still on the stack when the
/// grant is bound, so Past in Flames keeps only its own printed flashback.
#[test]
fn past_in_flames_does_not_grant_itself() {
    let Board {
        runner,
        past_in_flames,
        pyretic_ritual,
        ..
    } = board_after_past_in_flames();
    assert_eq!(
        runner.state().objects[&past_in_flames].zone,
        Zone::Graveyard
    );
    assert_eq!(
        flashbacks(&runner, past_in_flames),
        vec![printed_flashback(4, vec![ManaCostShard::Red])]
    );
    assert_eq!(
        display_spell_cost(runner.state(), P0, past_in_flames),
        Some(cost(4, vec![ManaCostShard::Red]))
    );
    // Reach-guard: the cards that were in the graveyard did get the grant.
    assert_eq!(
        flashbacks(&runner, pyretic_ritual),
        vec![granted_flashback()]
    );
}

/// An empty graveyard binds nothing and resolves cleanly. This also holds
/// without the change, so it is a boundary check and not a discriminating row.
#[test]
fn past_in_flames_with_an_empty_graveyard_installs_nothing() {
    let mut scenario = GameScenario::new();
    scenario.at_phase(Phase::PreCombatMain);
    let past_in_flames = scenario
        .add_spell_to_hand_from_oracle(P0, "Past in Flames", false, PAST_IN_FLAMES)
        .with_mana_cost(cost(3, vec![ManaCostShard::Red]))
        .id();
    pool(&mut scenario, "CCCR");
    let mut runner = scenario.build();

    runner.cast(past_in_flames).resolve();

    assert_eq!(
        runner.state().objects[&past_in_flames].zone,
        Zone::Graveyard
    );
    assert_eq!(grants_from(&runner, past_in_flames), 0);
    assert_settled(&runner);
}

/// Backdraft Hellkite's attack trigger is the second producer of the same
/// grant. Hellkite leaves the battlefield with the trigger on the stack; the
/// trigger still resolves and grants (ruling 2019-08-23). A card put into the
/// graveyard after the resolution gains nothing.
#[test]
fn backdraft_hellkite_attack_grants_flashback_even_if_it_leaves() {
    let mut scenario = GameScenario::new();
    scenario.at_phase(Phase::PreCombatMain);
    let hellkite = scenario
        .add_creature_from_oracle(P0, "Backdraft Hellkite", 4, 4, BACKDRAFT_HELLKITE)
        .with_subtypes(vec!["Dragon"])
        .with_mana_cost(cost(3, vec![ManaCostShard::Red, ManaCostShard::Red]))
        .id();
    let pyretic_ritual = scenario
        .add_spell_to_graveyard(P0, "Pyretic Ritual", true)
        .with_mana_cost(one_red())
        .from_oracle_text(PYRETIC_RITUAL)
        .id();
    let late_ritual = scenario
        .add_spell_to_hand_from_oracle(P0, "Pyretic Ritual", true, PYRETIC_RITUAL)
        .with_mana_cost(one_red())
        .id();
    library(&mut scenario, P0, 3);
    library(&mut scenario, P1, 3);
    let mut runner = scenario.build();

    assert!(
        flashbacks(&runner, pyretic_ritual).is_empty(),
        "before the attack"
    );
    runner.advance_to_combat();
    runner
        .declare_attackers(&[(hellkite, AttackTarget::Player(P1))])
        .expect("Backdraft Hellkite attacks");
    move_card(&mut runner, hellkite, Zone::Exile);
    for _ in 0..40 {
        match &runner.state().waiting_for {
            WaitingFor::Priority { .. }
                if runner.state().phase == Phase::PostCombatMain
                    && runner.state().stack.is_empty() =>
            {
                break
            }
            WaitingFor::Priority { .. } => {
                runner
                    .act(GameAction::PassPriority)
                    .expect("priority passes");
            }
            WaitingFor::DeclareBlockers { .. } => {
                runner
                    .act(GameAction::DeclareBlockers {
                        assignments: vec![],
                    })
                    .expect("no blockers");
            }
            other => panic!("unexpected prompt {other:?}"),
        }
    }
    assert_eq!(runner.state().phase, Phase::PostCombatMain);
    assert_eq!(runner.state().objects[&hellkite].zone, Zone::Exile);
    move_card(&mut runner, late_ritual, Zone::Graveyard);
    fund(&mut runner, "CR");

    assert_eq!(
        flashbacks(&runner, pyretic_ritual),
        vec![granted_flashback()]
    );
    assert!(
        casts_offered(&runner, pyretic_ritual) >= 1,
        "postcombat main"
    );
    assert!(flashbacks(&runner, late_ritual).is_empty());
    assert_eq!(casts_offered(&runner, late_ritual), 0);
}

/// The Grim Captain's Locker gives each creature card in the graveyard
/// escape (CR 702.138a) until end of turn; the cast pays the escape cost and
/// exiles four other graveyard cards.
#[test]
fn grim_captains_locker_grants_escape_to_the_creature_cards() {
    let mut scenario = GameScenario::new();
    scenario.at_phase(Phase::PreCombatMain);
    let locker = scenario
        .add_artifact_from_oracle(P0, "The Grim Captain's Locker", GRIM_CAPTAINS_LOCKER)
        .as_legendary()
        .with_mana_cost(cost(3, vec![ManaCostShard::Black]))
        .id();
    let grizzly_bears = scenario
        .add_creature_to_graveyard(P0, "Grizzly Bears", 2, 2)
        .with_subtypes(vec!["Bear"])
        .with_mana_cost(cost(1, vec![ManaCostShard::Green]))
        .id();
    let pyretic_ritual = scenario
        .add_spell_to_graveyard(P0, "Pyretic Ritual", true)
        .with_mana_cost(one_red())
        .from_oracle_text(PYRETIC_RITUAL)
        .id();
    scenario.with_graveyard(P0, &["Other 0", "Other 1", "Other 2", "Other 3"]);
    let opposing_bears = scenario
        .add_creature_to_graveyard(P1, "Grizzly Bears", 2, 2)
        .with_subtypes(vec!["Bear"])
        .with_mana_cost(cost(1, vec![ManaCostShard::Green]))
        .id();
    library(&mut scenario, P0, 3);
    let mut runner = scenario.build();

    let escapes = |runner: &GameRunner, card| {
        effective_keyword_instances(runner.state(), card, KeywordKind::Escape)
    };
    assert!(
        escapes(&runner, grizzly_bears).is_empty(),
        "before the activation"
    );
    assert_eq!(casts_offered(&runner, grizzly_bears), 0);

    runner.activate(locker, 1).resolve();
    assert_settled(&runner);
    assert!(
        runner.state().objects[&locker].tapped,
        "the Locker's {{T}} ability resolved"
    );
    fund(&mut runner, "CCCB");

    let granted = escapes(&runner, grizzly_bears);
    assert_eq!(granted.len(), 1, "{granted:?}");
    assert!(casts_offered(&runner, grizzly_bears) >= 1, "offered");
    assert!(escapes(&runner, pyretic_ritual).is_empty(), "an instant");
    assert!(escapes(&runner, opposing_bears).is_empty(), "owner scope");

    let graveyard_before = runner.state().players[0].graveyard.len();
    let fodder: Vec<ObjectId> = runner.state().players[0]
        .graveyard
        .iter()
        .copied()
        .filter(|id| *id != grizzly_bears)
        .take(4)
        .collect();
    runner
        .cast(grizzly_bears)
        .casting_variant(CastingVariant::Escape)
        .casting_keyword(granted[0].clone())
        .pay_cost_with(&fodder)
        .decline_optional()
        .resolve();
    assert_eq!(
        runner.state().objects[&grizzly_bears].zone,
        Zone::Battlefield
    );
    assert_eq!(
        graveyard_before - runner.state().players[0].graveyard.len(),
        5,
        "the creature and the four cards exiled to pay"
    );
    assert_only_the_spare_is_left(&runner);
}

/// Ghost Ark's crew trigger gives each artifact creature card in the graveyard
/// unearth {3} (CR 702.84a) until end of turn; an artifact creature card that
/// reaches the graveyard afterward does not get it (CR 611.2c).
#[test]
fn ghost_ark_crew_trigger_grants_unearth_to_the_artifact_creature_cards() {
    let mut scenario = GameScenario::new();
    scenario.at_phase(Phase::PreCombatMain);
    let ark = scenario
        .add_artifact_from_oracle(P0, "Ghost Ark", GHOST_ARK)
        .with_subtypes(vec!["Vehicle"])
        .with_mana_cost(cost(4, vec![]))
        .id();
    let pilot = scenario
        .add_creature(P0, "Grizzly Bears", 2, 2)
        .with_subtypes(vec!["Bear"])
        .id();
    let ornithopter = scenario
        .add_creature_to_graveyard(P0, "Ornithopter", 0, 2)
        .as_artifact_creature()
        .with_subtypes(vec!["Thopter"])
        .flying()
        .with_mana_cost(ManaCost::zero())
        .id();
    let grizzly_bears = scenario
        .add_creature_to_graveyard(P0, "Grizzly Bears", 2, 2)
        .with_subtypes(vec!["Bear"])
        .with_mana_cost(cost(1, vec![ManaCostShard::Green]))
        .id();
    let pyretic_ritual = scenario
        .add_spell_to_graveyard(P0, "Pyretic Ritual", true)
        .with_mana_cost(one_red())
        .from_oracle_text(PYRETIC_RITUAL)
        .id();
    let late_artifact_creature = scenario
        .add_creature_to_hand(P0, "Ornithopter", 0, 2)
        .as_artifact_creature()
        .with_subtypes(vec!["Thopter"])
        .flying()
        .with_mana_cost(ManaCost::zero())
        .id();
    library(&mut scenario, P0, 3);
    let mut runner = scenario.build();
    let ark_object = runner.state_mut().objects.get_mut(&ark).expect("the Ark");
    ark_object.base_power = Some(3);
    ark_object.base_toughness = Some(3);
    ark_object.power = Some(3);
    ark_object.toughness = Some(3);

    let unearths = |runner: &GameRunner, card| {
        effective_keyword_instances(runner.state(), card, KeywordKind::Unearth)
    };
    let activations = |runner: &GameRunner, card| -> Vec<usize> {
        legal_actions(runner.state())
            .into_iter()
            .filter_map(|action| match action {
                GameAction::ActivateAbility {
                    source_id,
                    ability_index,
                    ..
                } if source_id == card => Some(ability_index),
                _ => None,
            })
            .collect()
    };
    fund(&mut runner, "CCC");
    assert!(unearths(&runner, ornithopter).is_empty(), "before the crew");
    assert!(activations(&runner, ornithopter).is_empty());

    runner
        .act(GameAction::CrewVehicle {
            vehicle_id: ark,
            creature_ids: vec![],
        })
        .expect("enter crew mode");
    runner
        .act(GameAction::CrewVehicle {
            vehicle_id: ark,
            creature_ids: vec![pilot],
        })
        .expect("crew with the 2/2");
    runner.advance_until_stack_empty();
    assert_settled(&runner);
    move_card(&mut runner, late_artifact_creature, Zone::Graveyard);

    assert_eq!(unearths(&runner, ornithopter).len(), 1);
    assert!(
        unearths(&runner, grizzly_bears).is_empty(),
        "not an artifact"
    );
    assert!(
        unearths(&runner, pyretic_ritual).is_empty(),
        "not a creature"
    );
    assert!(
        unearths(&runner, late_artifact_creature).is_empty(),
        "came later"
    );
    assert!(activations(&runner, late_artifact_creature).is_empty());
    assert!(activations(&runner, grizzly_bears).is_empty());
    let offered = activations(&runner, ornithopter);
    assert_eq!(offered.len(), 1, "the unearth: {offered:?}");

    runner.activate(ornithopter, offered[0]).resolve();
    assert_eq!(runner.state().objects[&ornithopter].zone, Zone::Battlefield);
    assert_only_the_spare_is_left(&runner);
}

/// Ruling {X}: Blaze {X}{R} gets the granted flashback; X is chosen as part of
/// the cast (CR 107.3a) and paid on top of the {R}.
#[test]
fn a_granted_flashback_cast_still_chooses_x() {
    let mut scenario = GameScenario::new();
    scenario.at_phase(Phase::PreCombatMain);
    let blaze = scenario
        .add_spell_to_graveyard(P0, "Blaze", false)
        .with_mana_cost(cost(0, vec![ManaCostShard::X, ManaCostShard::Red]))
        .from_oracle_text(BLAZE)
        .id();
    let past_in_flames = scenario
        .add_spell_to_hand_from_oracle(P0, "Past in Flames", false, PAST_IN_FLAMES)
        .with_mana_cost(cost(3, vec![ManaCostShard::Red]))
        .id();
    library(&mut scenario, P0, 2);
    pool(&mut scenario, "CCCR");
    let mut runner = scenario.build();
    assert!(
        flashbacks(&runner, blaze).is_empty(),
        "before Past in Flames"
    );
    assert_eq!(casts_offered(&runner, blaze), 0);

    runner.cast(past_in_flames).resolve();
    fund(&mut runner, "CCR");

    assert_eq!(flashbacks(&runner, blaze), vec![granted_flashback()]);
    let prompt = prompt_after_target(&runner, blaze, P1);
    assert!(
        matches!(prompt, WaitingFor::ChooseXValue { .. }),
        "X is chosen as part of the cast, got {prompt:?}"
    );
    runner.cast(blaze).x(2).target_player(P1).resolve();
    assert_eq!(runner.life(P1), 18);
    assert_eq!(runner.state().objects[&blaze].zone, Zone::Exile);
    assert_only_the_spare_is_left(&runner);
}

/// Ruling "mandatory additional costs": Tormenting Voice's discard is still
/// paid under the granted flashback.
#[test]
fn a_granted_flashback_cast_pays_the_mandatory_additional_cost() {
    let mut scenario = GameScenario::new();
    scenario.at_phase(Phase::PreCombatMain);
    let voice = scenario
        .add_spell_to_graveyard(P0, "Tormenting Voice", false)
        .with_mana_cost(one_red())
        .from_oracle_text(TORMENTING_VOICE)
        .id();
    let past_in_flames = scenario
        .add_spell_to_hand_from_oracle(P0, "Past in Flames", false, PAST_IN_FLAMES)
        .with_mana_cost(cost(3, vec![ManaCostShard::Red]))
        .id();
    let filler = scenario.add_card_to_hand(P0, "Filler card");
    library(&mut scenario, P0, 3);
    pool(&mut scenario, "CCCR");
    let mut runner = scenario.build();
    runner.cast(past_in_flames).resolve();
    fund(&mut runner, "CR");
    assert_eq!(flashbacks(&runner, voice), vec![granted_flashback()]);

    runner.cast(voice).pay_cost_with(&[filler]).resolve();

    assert_eq!(runner.state().objects[&filler].zone, Zone::Graveyard);
    assert_eq!(runner.state().players[0].hand.len(), 2, "drew two");
    assert_eq!(runner.state().objects[&voice].zone, Zone::Exile);
    assert_only_the_spare_is_left(&runner);
}

/// The same card with nothing to discard: the additional cost can't be paid,
/// so the cast is not offered though the grant and the mana are there.
#[test]
fn a_granted_flashback_cast_is_not_offered_when_its_additional_cost_cannot_be_paid() {
    let mut scenario = GameScenario::new();
    scenario.at_phase(Phase::PreCombatMain);
    let voice = scenario
        .add_spell_to_graveyard(P0, "Tormenting Voice", false)
        .with_mana_cost(one_red())
        .from_oracle_text(TORMENTING_VOICE)
        .id();
    let past_in_flames = scenario
        .add_spell_to_hand_from_oracle(P0, "Past in Flames", false, PAST_IN_FLAMES)
        .with_mana_cost(cost(3, vec![ManaCostShard::Red]))
        .id();
    library(&mut scenario, P0, 3);
    pool(&mut scenario, "CCCR");
    let mut runner = scenario.build();
    runner.cast(past_in_flames).resolve();
    fund(&mut runner, "CR");

    assert_eq!(flashbacks(&runner, voice), vec![granted_flashback()]);
    assert_eq!(
        display_spell_cost(runner.state(), P0, voice),
        Some(one_red()),
        "reach-guard: the mana cost is the flashback cost and the pool pays it"
    );
    assert!(
        runner.state().players[0].hand.is_empty(),
        "nothing to discard"
    );
    assert_eq!(casts_offered(&runner, voice), 0);
}

/// Ruling split card: Fire // Ice gets the granted flashback and the cast pays
/// only the cost of the half cast: {1}{U} for Ice (CR 709.3a, CR 709.3b).
#[test]
fn a_split_card_pays_only_the_half_it_casts() {
    let Some(db) = shared_card_db() else {
        return;
    };
    let build = || {
        let mut scenario = GameScenario::new();
        scenario.at_phase(Phase::PreCombatMain);
        let fire = scenario.add_real_card(P0, "Fire", Zone::Graveyard, db);
        let past_in_flames = scenario
            .add_spell_to_hand_from_oracle(P0, "Past in Flames", false, PAST_IN_FLAMES)
            .with_mana_cost(cost(3, vec![ManaCostShard::Red]))
            .id();
        let target = scenario
            .add_creature(P1, "Grizzly Bears", 2, 2)
            .with_subtypes(vec!["Bear"])
            .id();
        library(&mut scenario, P0, 3);
        pool(&mut scenario, "CCCR");
        let mut runner = scenario.build();
        engine::game::rehydrate_game_from_card_db(runner.state_mut(), db);
        runner.cast(past_in_flames).resolve();
        (runner, fire, target)
    };

    let (mut runner, fire, target) = build();
    assert_eq!(flashbacks(&runner, fire), vec![granted_flashback()]);
    fund(&mut runner, "CU");
    let commit = runner
        .cast(fire)
        .modal_back_face(true)
        .target_object(target)
        .commit();
    let on_stack = commit.state().stack.last().map(|entry| entry.source_id);
    let name = on_stack.map(|id| commit.state().objects[&id].name.clone());
    assert_eq!(name.as_deref(), Some("Ice"), "the Ice half is on the stack");
    let outcome = commit.resolve();
    outcome.assert_zone(&[fire], Zone::Exile);
    outcome.assert_hand_drawn(P0, 1);
    assert_only_the_spare_is_left(&runner);

    // Paired choice: with {R} and {C} the Fire half is the one that is paid.
    let (mut runner, fire, target) = build();
    fund(&mut runner, "CR");
    let commit = runner
        .cast(fire)
        .modal_back_face(false)
        .target_object(target)
        .commit();
    let on_stack = commit.state().stack.last().map(|entry| entry.source_id);
    let name = on_stack.map(|id| commit.state().objects[&id].name.clone());
    assert_eq!(
        name.as_deref(),
        Some("Fire"),
        "the Fire half is on the stack"
    );
    commit.resolve();
    assert_eq!(runner.state().objects[&fire].zone, Zone::Exile);
    assert_only_the_spare_is_left(&runner);
}
